//! `iron_ts_rt`: the runtime that code generated by `iron_ts` calls into.
//!
//! Memory model of the spike: one **bump arena**, never freed. Objects, arrays and strings are
//! allocated from 4 MiB zeroed chunks and are only reclaimed when the whole arena is dropped
//! (`reset`). That is enough for a pure simulation stepped a few thousand times, and it keeps
//! every allocation a pointer bump. The headroom a real collector needs is written down in
//! `docs/research/iron-ts-spike.md` (stack maps or a shadow stack for roots, a header on each
//! object, which every object here already has).
//!
//! Layouts (all 8-byte slots, little endian):
//! - object: `[header: u64 = struct id + 1][field 0][field 1]...`
//! - array: `Array { header, len, cap, data }`, `data` holds `cap` 8-byte slots (`Bytes`: bytes)
//! - string: `Str { header, len, data }`, UTF-8
//!
//! The arena is thread local: no locking, and parallel tests get separate heaps.

use std::alloc::{Layout, alloc_zeroed};
use std::cell::UnsafeCell;

const CHUNK: usize = 4 << 20;

struct Arena {
    cur: *mut u8,
    end: *mut u8,
    chunks: Vec<(*mut u8, usize)>,
    allocated: usize,
}

thread_local! {
    static ARENA: UnsafeCell<Arena> = const { UnsafeCell::new(Arena { cur: std::ptr::null_mut(), end: std::ptr::null_mut(), chunks: Vec::new(), allocated: 0 }) };
}

/// Runs `f` on this thread's arena. Each thread has its own heap, so objects must stay on the
/// thread that made them (a game's scripts run on one thread).
fn with_arena<T>(f: impl FnOnce(&mut Arena) -> T) -> T {
    // SAFETY: thread local, and `f` does not re-enter the arena.
    ARENA.with(|a| f(unsafe { &mut *a.get() }))
}

fn new_chunk(size: usize) -> *mut u8 {
    let layout = Layout::from_size_align(size, 16).unwrap();
    // SAFETY: non-zero size, valid layout.
    let p = unsafe { alloc_zeroed(layout) };
    assert!(!p.is_null(), "out of memory");
    with_arena(|a| a.chunks.push((p, size)));
    p
}

/// Zeroed, 16-byte aligned memory that lives until `ts_rt_reset`.
#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_alloc(size: usize) -> *mut u8 {
    let size = (size + 15) & !15;
    // Fast path: one thread-local access, a bump.
    let fast = with_arena(|a| {
        a.allocated += size;
        let left = (a.end as usize) - (a.cur as usize);
        if size <= CHUNK / 4 && !a.cur.is_null() && left >= size {
            let p = a.cur;
            // SAFETY: checked above that `size` fits in the chunk.
            a.cur = unsafe { p.add(size) };
            p
        } else {
            std::ptr::null_mut()
        }
    });
    if !fast.is_null() {
        return fast;
    }
    if size > CHUNK / 4 {
        return new_chunk(size);
    }
    let p = new_chunk(CHUNK);
    with_arena(|a| {
        // SAFETY: `p` points to `CHUNK` bytes and `size` <= CHUNK.
        a.cur = unsafe { p.add(size) };
        a.end = unsafe { p.add(CHUNK) };
    });
    p
}

/// Bytes handed out since the last reset.
#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_allocated() -> usize {
    with_arena(|a| a.allocated)
}

/// Frees everything but the first chunk, which is zeroed and reused (a per-frame arena should
/// not hand 4 MiB back to the OS and fault it in again every frame). Every pointer previously
/// returned is dangling afterwards.
#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_reset() {
    with_arena(|a| {
        let keep = a.chunks.iter().position(|(_, size)| *size == CHUNK);
        for (i, (p, size)) in std::mem::take(&mut a.chunks).into_iter().enumerate() {
            if Some(i) == keep {
                let used = if (a.cur as usize) >= (p as usize)
                    && (a.cur as usize) <= (p as usize) + CHUNK
                {
                    a.cur as usize - p as usize
                } else {
                    CHUNK
                };
                // SAFETY: `p` points to `CHUNK` bytes, `used` of them were handed out.
                unsafe { std::ptr::write_bytes(p, 0, used) };
                a.chunks.push((p, size));
                a.cur = p;
                // SAFETY: within the chunk.
                a.end = unsafe { p.add(CHUNK) };
            } else {
                // SAFETY: allocated with this layout in `new_chunk`.
                unsafe { std::alloc::dealloc(p, Layout::from_size_align(size, 16).unwrap()) };
            }
        }
        if keep.is_none() {
            a.cur = std::ptr::null_mut();
            a.end = std::ptr::null_mut();
        }
        a.allocated = 0;
    })
}

#[repr(C)]
pub struct Array {
    pub header: u64,
    pub len: i64,
    pub cap: i64,
    pub data: *mut u8,
}

/// Header words (so a collector or debugger can tell the kinds apart).
pub const HDR_ARRAY: u64 = 0xA11A_0001;
pub const HDR_BYTES: u64 = 0xA11A_0002;
pub const HDR_STR: u64 = 0xA11A_0003;
pub const HDR_CLOSURE: u64 = 0xA11A_0004;

#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_arr_new(cap: i64) -> *mut Array {
    let a = ts_rt_alloc(std::mem::size_of::<Array>()) as *mut Array;
    let cap = cap.max(0);
    // SAFETY: freshly allocated, large enough.
    unsafe {
        (*a).header = HDR_ARRAY;
        (*a).cap = cap;
        if cap > 0 {
            (*a).data = ts_rt_alloc(cap as usize * 8);
        }
    }
    a
}

/// # Safety
/// `a` must be an array from `ts_rt_arr_new`.
///
/// Appends one 8-byte slot (a number's bits, a pointer, a bool, a tag).
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ts_rt_arr_push(a: *mut Array, v: u64) {
    // SAFETY: `a` is an array made by `ts_rt_arr_new`.
    unsafe {
        let arr = &mut *a;
        if arr.len == arr.cap {
            let ncap = (arr.cap * 2).max(4);
            let nd = ts_rt_alloc(ncap as usize * 8);
            if arr.len > 0 {
                std::ptr::copy_nonoverlapping(arr.data, nd, arr.len as usize * 8);
            }
            arr.data = nd;
            arr.cap = ncap;
        }
        *(arr.data as *mut u64).add(arr.len as usize) = v;
        arr.len += 1;
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_bytes_new(len: i64) -> *mut Array {
    let a = ts_rt_alloc(std::mem::size_of::<Array>()) as *mut Array;
    let len = len.max(0);
    // SAFETY: freshly allocated.
    unsafe {
        (*a).header = HDR_BYTES;
        (*a).len = len;
        (*a).cap = len;
        (*a).data = ts_rt_alloc(len as usize);
    }
    a
}

/// `bytes.fill(value, start, end)` with JS clamping to the length.
///
/// # Safety
/// `a` must be a byte array from `ts_rt_bytes_new`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ts_rt_bytes_fill(a: *mut Array, value: i64, start: i64, end: i64) {
    // SAFETY: `a` is a byte array.
    unsafe {
        let arr = &*a;
        let s = start.clamp(0, arr.len);
        let e = end.clamp(s, arr.len);
        std::ptr::write_bytes(arr.data.add(s as usize), value as u8, (e - s) as usize);
    }
}

// ---- math the generated code does not inline ----

#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_fmod(a: f64, b: f64) -> f64 {
    a % b
}
#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_sin(a: f64) -> f64 {
    a.sin()
}
#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_cos(a: f64) -> f64 {
    a.cos()
}
#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_atan2(y: f64, x: f64) -> f64 {
    y.atan2(x)
}
#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_hypot(a: f64, b: f64) -> f64 {
    a.hypot(b)
}

// ---- strings (the runtime side; lowering of general string code is future work) ----

#[repr(C)]
pub struct Str {
    pub header: u64,
    pub len: i64,
    pub data: *const u8,
}

/// # Safety
/// `data` must point to `len` readable bytes.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ts_rt_str_new(data: *const u8, len: i64) -> *mut Str {
    let s = ts_rt_alloc(std::mem::size_of::<Str>()) as *mut Str;
    let copy = ts_rt_alloc(len.max(0) as usize);
    // SAFETY: `data` has `len` bytes by contract; `copy` was just allocated.
    unsafe {
        std::ptr::copy_nonoverlapping(data, copy, len.max(0) as usize);
        (*s).header = HDR_STR;
        (*s).len = len;
        (*s).data = copy;
    }
    s
}

/// # Safety
/// Both must be strings made by `ts_rt_str_new`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ts_rt_str_concat(a: *const Str, b: *const Str) -> *mut Str {
    // SAFETY: both are strings made by `ts_rt_str_new`.
    unsafe {
        let (la, lb) = ((*a).len as usize, (*b).len as usize);
        let buf = ts_rt_alloc(la + lb);
        std::ptr::copy_nonoverlapping((*a).data, buf, la);
        std::ptr::copy_nonoverlapping((*b).data, buf.add(la), lb);
        ts_rt_str_new(buf, (la + lb) as i64)
    }
}

/// # Safety
/// Both must be strings made by `ts_rt_str_new`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ts_rt_str_eq(a: *const Str, b: *const Str) -> bool {
    // SAFETY: both are strings.
    unsafe {
        (*a).len == (*b).len
            && std::slice::from_raw_parts((*a).data, (*a).len as usize)
                == std::slice::from_raw_parts((*b).data, (*b).len as usize)
    }
}

/// A function pointer plus environment, the representation of a function-typed value.
#[repr(C)]
pub struct Closure {
    pub header: u64,
    pub func: *const u8,
    pub env: *mut u8,
}

#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_closure_new(func: *const u8, env: *mut u8) -> *mut Closure {
    let c = ts_rt_alloc(std::mem::size_of::<Closure>()) as *mut Closure;
    // SAFETY: freshly allocated.
    unsafe {
        (*c).header = HDR_CLOSURE;
        (*c).func = func;
        (*c).env = env;
    }
    c
}

/// Reading helpers for hosts (the test harness) that look inside arrays.
impl Array {
    /// # Safety
    /// `i` must be in range and the slots must hold `T`.
    pub unsafe fn get<T: Copy>(&self, i: usize) -> T {
        unsafe { *(self.data as *const T).add(i) }
    }
    pub fn len(&self) -> usize {
        self.len as usize
    }
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }
    /// # Safety
    /// This must be a byte array.
    pub unsafe fn bytes(&self) -> &[u8] {
        unsafe { std::slice::from_raw_parts(self.data, self.len as usize) }
    }
}

/// Keeps the exported symbols linked into an executable that only reaches them from generated code.
pub fn link_anchor() -> usize {
    [
        ts_rt_alloc as *const () as usize,
        ts_rt_arr_new as *const () as usize,
        ts_rt_arr_push as *const () as usize,
        ts_rt_bytes_new as *const () as usize,
        ts_rt_bytes_fill as *const () as usize,
        ts_rt_fmod as *const () as usize,
        ts_rt_sin as *const () as usize,
        ts_rt_cos as *const () as usize,
        ts_rt_atan2 as *const () as usize,
        ts_rt_hypot as *const () as usize,
        ts_rt_str_new as *const () as usize,
        ts_rt_closure_new as *const () as usize,
    ]
    .iter()
    .sum()
}

#[cfg(test)]
mod tests {
    use super::*;

    // TS-RT-01
    #[test]
    fn arrays_grow_and_keep_their_values() {
        let a = ts_rt_arr_new(0);
        for i in 0..100u64 {
            unsafe { ts_rt_arr_push(a, i * 3) };
        }
        let a = unsafe { &*a };
        assert_eq!(a.len(), 100);
        assert_eq!(unsafe { a.get::<u64>(99) }, 297);
    }

    // TS-RT-02
    #[test]
    fn strings_concat_and_compare() {
        let a = unsafe { ts_rt_str_new(b"zom".as_ptr(), 3) };
        let b = unsafe { ts_rt_str_new(b"bie".as_ptr(), 3) };
        let c = unsafe { ts_rt_str_concat(a, b) };
        let d = unsafe { ts_rt_str_new(b"zombie".as_ptr(), 6) };
        assert!(unsafe { ts_rt_str_eq(c, d) });
        assert!(!unsafe { ts_rt_str_eq(a, b) });
    }

    // TS-RT-03
    #[test]
    fn byte_fill_clamps_to_the_length() {
        let a = ts_rt_bytes_new(8);
        unsafe { ts_rt_bytes_fill(a, 1, 6, 100) };
        assert_eq!(unsafe { (*a).bytes() }, &[0, 0, 0, 0, 0, 0, 1, 1]);
    }

    // M9-TS-20
    #[test]
    fn reset_reuses_the_first_chunk_and_hands_out_zeroed_memory() {
        let a = ts_rt_alloc(64);
        unsafe { std::ptr::write_bytes(a, 0xAB, 64) };
        ts_rt_reset();
        let b = ts_rt_alloc(64);
        assert_eq!(a, b);
        assert!(
            unsafe { std::slice::from_raw_parts(b, 64) }
                .iter()
                .all(|x| *x == 0)
        );
        assert_eq!(ts_rt_allocated(), 64);
    }
}
